import base64, json, urllib.request

BASE = 'https://api.ivxholding.com'
TOKEN = open('/tmp/owner_token.txt').read().strip()

for path in [
    'expo/scripts/trigger-render-deploy.mjs',
    'expo/scripts/update-render-env.mjs',
    'backend/api/ivx-version-endpoint.ts',
    'backend/api/owner-routes.ts',
    'deploy/deployment-watchdog.mjs',
    'expo/deploy/scripts/render-env-debug.mjs'
]:
    payload = {
        'action': 'github_read_file',
        'input': {'path': path, 'branch': 'main'}
    }
    req = urllib.request.Request(f'{BASE}/api/ivx/developer-deploy/action',
        data=json.dumps(payload).encode(),
        headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {TOKEN}'},
        method='POST')
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            result = json.loads(r.read()).get('result', {})
            content_raw = result.get('content', '')
            try:
                content = base64.b64decode(content_raw).decode('utf-8')
            except Exception:
                content = content_raw
            print(f'\n=== {path} ===')
            # Extract service ID references
            for keyword in ['srv-', 'RENDER_SERVICE_ID', 'ivx-owner-ai-backend', 'ivx-holdings-platform']:
                idx = 0
                while True:
                    idx = content.find(keyword, idx)
                    if idx == -1:
                        break
                    start = max(0, idx - 50)
                    end = min(len(content), idx + 100)
                    print(f'  {content[start:end].replace(chr(10), " ")}')
                    idx += len(keyword)
    except Exception as e:
        print(f'{path}: error {e}')
